39	export const CHECKS = '.claudinite-checks.json';
40	export const SETTINGS = '.claude/settings.json';
41	export const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';
42	
43	// A probe result. `ok: null` means NOT APPLICABLE — the thing this probe would
44	// judge is legitimately absent (no scheduler in a repo that never cut over, no
45	// local packs declared). Not-applicable is never a failure; conflating the two
46	// is how a check earns its reputation for crying wolf.
47	export const pass = (id) => ({ id, ok: true });
48	export const skip = (id, why) => ({ id, ok: null, detail: why });
49	export const fail = (id, detail, fix) => ({ id, ok: false, detail, fix });
50	
51	// The verdict over a probe set. Exit code is the caller's business — this only
52	// says what happened, so both callers (a session-start step that must never
53	// block, and a strict CI/bootstrap run that must) read the same result.
54	export function report(probes) {
55	  const failures = probes.filter((p) => p.ok === false);
56	  const ran = probes.filter((p) => p.ok !== null).length;
57	  return {
58	    ok: failures.length === 0,
59	    ran,
60	    skipped: probes.length - ran,
61	    failures,
62	    summary: failures.length
63	      ? `Claudinite self-test: ${failures.length} of ${ran} probes FAILED — ${failures.map((f) => f.id).join(', ')}`
64	      : `Claudinite self-test: ${ran} probes passed.`,
65	  };
66	}
