74	export function probeMount(io) {
75	  if (!io.exists(MOUNT)) return skip('mount', 'no vendored mount — this is the canon itself, or a repo that has not adopted');
76	  if (!io.exists(`${MOUNT}/engine/checks/check_the_world.mjs`)) {
77	    return fail('mount', `${MOUNT} exists but carries no engine`, 're-run the update task, or bootstrap this repo — the mount is incomplete');
78	  }
79	  return pass('mount');
80	}
