82	export function probeStamp(io) {
83	  const raw = io.read(CHECKS);
84	  if (raw === null) return fail('stamp', `${CHECKS} is missing`, 'run bootstrap --init to write the declaration');
85	  let cfg;
86	  try { cfg = JSON.parse(raw); } catch (e) {
87	    return fail('stamp', `${CHECKS} is not valid JSON: ${e.message}`, 'fix the JSON syntax — nothing can read the declaration until it parses');
88	  }
89	  if (!io.exists(MOUNT)) return skip('stamp', 'no vendored mount to stamp');
90	  const s = cfg.claudinite;
91	  if (!s || typeof s.updated !== 'string' || !s.updated) {
92	    return fail('stamp', 'the mount is present but carries no claudinite.updated stamp',
93	      'the update flows read this to decide what to apply — a missing stamp makes the task self-skip forever (#518)');
94	  }
95	  return pass('stamp');
96	}
97	
98	// The #555 probe. A manifest the loader rejects means that pack's rules never
99	// run — silently, because normalizeManifest rebuilds `rules` from the scoped
100	// lists and an unvalidated manifest contributes none.
101	export function probePackManifests(loaded) {
102	  if (!loaded) return skip('pack-manifests', 'the pack loader could not be reached from here');
103	  if (loaded.errors?.length) {
104	    const first = loaded.errors[0];
105	    return fail('pack-manifests', `${loaded.errors.length} pack(s) failed to load or validate — first: ${first.what ?? first}`,
106	      first.fix ?? 'fix the manifest — a pack that does not validate contributes no rules, so its checks stop running with no other symptom');
107	  }
108	  if (!loaded.packs?.length) return fail('pack-manifests', 'no packs were discovered at all', 'check the mount and the declaration — a session with no packs enforces nothing');
109	  return pass('pack-manifests');
110	}
