117	    return fail('hook-targets', `${SETTINGS} is not valid JSON: ${e.message}`, 'fix the JSON — the harness silently runs no hooks when its settings will not parse');
118	  }
119	  const missing = [];
120	  for (const entries of Object.values(cfg.hooks ?? {})) {
121	    for (const entry of Array.isArray(entries) ? entries : []) {
122	      for (const hook of entry.hooks ?? []) {
123	        const cmd = String(hook.command ?? '');
124	        // The path inside the command, with the harness's variable resolved.
125	        const m = cmd.match(/\$CLAUDE_PROJECT_DIR\/(\S+)/);
126	        if (m && !io.exists(m[1])) missing.push(m[1]);
127	      }
128	    }
129	  }
130	  if (missing.length) {
131	    return fail('hook-targets', `${missing.length} hook command(s) point at files that do not exist: ${missing.join(', ')}`,
132	      're-run the update task to converge the wiring — a hook whose target is missing fails silently every session (#397)');
133	  }
134	  return pass('hook-targets');
135	}
136	
137	export function probeSkillLinks(io) {
138	  const root = '.claude/skills';
139	  if (!io.exists(root)) return skip('skill-links', 'no mounted skills');
140	  const dangling = io.dangling(root);
141	  if (dangling.length) {
142	    return fail('skill-links', `${dangling.length} mounted skill link(s) dangle: ${dangling.slice(0, 5).join(', ')}`,
143	      're-run the skill mount (the update task does it) — a dangling link is a skill the session cannot load (#424)');
144	  }
145	  return pass('skill-links');
146	}
147	
148	export function probeScheduler(io) {
149	  const text = io.read(SCHEDULER);
150	  if (text === null) return skip('scheduler', 'no vendored scheduler workflow — this repo has not cut over to per-project scheduling');
151	  const crons = [...text.matchAll(/cron:\s*['"]?([^'"\n]+?)['"]?\s*$/gm)].map((m) => m[1].trim());
152	  if (crons.length !== 1) {
153	    return fail('scheduler', `the scheduler declares ${crons.length} cron schedules, expected exactly one`, 'keep a single hourly cron — the scheduler is the repo\'s only cron');
154	  }
155	  const parts = crons[0].split(/\s+/);
156	  if (parts.length !== 5 || !Number.isInteger(Number(parts[0]))) {
157	    return fail('scheduler', `the scheduler cron "${crons[0]}" does not parse as a 5-field expression with a fixed minute`,
158	      'set "<minute> * * * *" with the repo-hashed minute — an unparseable cron means the repo never runs a task again');
159	  }
160	  return pass('scheduler');
161	}
162	
163	export function probeMigrations(migrations) {
164	  if (migrations === null) return skip('migrations', 'no migrations registry reachable from here');
165	  if (migrations instanceof Error) {
166	    return fail('migrations', `the migrations registry failed to load: ${migrations.message}`,
167	      'a malformed record aborts every update run — fix or remove it');
168	  }
169	  return pass('migrations');
170	}
