174	function makeIo(root) {
175	  const abs = (p) => join(root, p);
176	  return {
177	    exists: (p) => existsSync(abs(p)),
178	    read: (p) => { try { return readFileSync(abs(p), 'utf8'); } catch { return null; } },
179	    // Symlinks under a directory whose targets do not resolve.
180	    dangling: (rel) => {
181	      const out = [];
182	      const walk = (dir) => {
183	        let entries = [];
184	        try { entries = readdirSync(abs(dir), { withFileTypes: true }); } catch { return; }
185	        for (const e of entries) {
186	          const p = `${dir}/${e.name}`;
187	          if (e.isSymbolicLink()) {
188	            try { realpathSync(abs(p)); } catch { out.push(p); }
189	          } else if (e.isDirectory()) walk(p);
190	        }
191	      };
192	      walk(rel);
193	      return out;
194	    },
195	    lstat: (p) => { try { return lstatSync(abs(p)); } catch { return null; } },
196	  };
197	}
