199	// Load the pack set and the migrations registry from whichever corpus this file
200	// is running out of — the canon root, or a consumer's vendored mount. Both are
201	// best-effort: a failure to reach them is a probe result, never a throw.
202	async function loadCorpus(root) {
203	  const corpus = dirname(dirname(fileURLToPath(import.meta.url))); // <corpus>/engine/ -> <corpus>
204	  let loaded = null;
205	  try {
206	    const { discoverPacks } = await import(pathToFileURL(join(corpus, 'engine/pack_loader/pack-registry.mjs')).href);
207	    loaded = await discoverPacks({ localRoot: root });
208	  } catch (e) { loaded = { packs: [], errors: [{ what: `the pack loader itself failed: ${e.message}`, fix: 'the engine is broken or half-vendored — re-run the update task' }] }; }
209	
210	  let migrations = null;
211	  // The registry moved under the engine with the engine/pack split; a mount that
212	  // has not converged since still carries the flat path, and probing it as absent
213	  // would report a HEALTHY-looking skip on a repo whose registry is right there.
214	  const regPath = [join(corpus, 'engine/migrations/registry.mjs'), join(corpus, 'migrations/registry.mjs')]
215	    .find((p) => existsSync(p));
216	  if (regPath) {
217	    try {
218	      const reg = await import(pathToFileURL(regPath).href);
219	      await reg.loadMigrations();
220	      migrations = true;
221	    } catch (e) { migrations = e; }
222	  }
223	  return { loaded, migrations };
224	}
225	
226	export async function runSelfTest(root) {
227	  const io = makeIo(root);
228	  const { loaded, migrations } = await loadCorpus(root);
229	  return report([
230	    probeMount(io),
231	    probeStamp(io),
232	    probePackManifests(loaded),
233	    probeHookTargets(io),
234	    probeSkillLinks(io),
235	    probeScheduler(io),
236	    probeMigrations(migrations),
237	  ]);
238	}
