241	// discards a hook's stdout on a non-zero exit — failing loudly there would
242	// destroy the very message it is trying to deliver. `--strict` exits 1 on
243	// failure, for bootstrap and for the update task's code-work, where a broken
244	// mechanism must stop the run rather than be reported into a void.
245	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
246	  const strict = process.argv.includes('--strict');
247	  const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
248	  const result = await runSelfTest(root);
249	  console.log(result.summary);
250	  for (const f of result.failures) console.log(`  - ${f.id}: ${f.detail}\n    fix: ${f.fix}`);
251	  process.exit(strict && !result.ok ? 1 : 0);
252	}
